export const ANNOTATE_CSS = "/* Annotate-mode styles, served at /_postplan/annotate.css and injected alongside the client.\n   Custom Highlight API paint for anchored comment ranges; span-wrap fallback uses .postplan-hl. */\n::highlight(postplan-comment) {\n  background-color: rgba(255, 213, 0, 0.4);\n}\n.postplan-hl {\n  background-color: rgba(255, 213, 0, 0.4);\n  cursor: pointer;\n}\n\n/* Mermaid lightbox: click a rendered diagram to blow it up in a native modal <dialog>.\n   Scoped to .mermaid (mermaid's own container class) so nothing else on the page changes. */\n.mermaid svg {\n  cursor: zoom-in;\n}\ndialog.postplan-lb {\n  border: 0;\n  padding: 0;\n  background: transparent;\n  width: 96vw;\n  max-width: 96vw;\n  max-height: 96vh;\n}\ndialog.postplan-lb::backdrop {\n  background: rgba(8, 10, 13, 0.93);\n}\ndialog.postplan-lb > div {\n  padding: 24px;\n  border-radius: 8px;\n  cursor: zoom-out;\n}\ndialog.postplan-lb svg {\n  display: block;\n  /* biome-ignore lint/complexity/noImportantStyles: Host page styles must not resize the lightbox image. */\n  width: 100% !important;\n  /* biome-ignore lint/complexity/noImportantStyles: Host page styles must not constrain the lightbox image. */\n  max-width: none !important;\n  height: auto;\n  max-height: 84vh;\n}\n"
